import { afterEach, describe, expect, it, vi } from 'vitest';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { RevisionPractice } from '@/components/testing/revision-practice';
import type { PracticeQuestion, RevisionGroup } from '@/lib/testing';
import { blank, incorrect, source } from './revision-fixtures';

afterEach(() => vi.unstubAllGlobals());

// Practice is generated by the server; fetch is the only mocked boundary.
function mountSelection(groups: RevisionGroup[], generated: PracticeQuestion[]) {
  const calls: { sourceIds: number[]; count: number }[] = [];
  vi.stubGlobal('fetch', vi.fn(async (_input: RequestInfo | URL, init?: RequestInit) => {
    const body = JSON.parse(String(init?.body)) as { sourceIds: number[]; count: number };
    calls.push(body);
    return Response.json(generated.filter(q => body.sourceIds.includes(q.sourceId)));
  }));
  const onBack = vi.fn();
  const onExit = vi.fn();
  const client = new QueryClient({ defaultOptions: { mutations: { retry: false } } });
  render(<QueryClientProvider client={client}><RevisionPractice groups={groups} sources={[source]} onBack={onBack} onExit={onExit} /></QueryClientProvider>);
  return { user: userEvent.setup(), onBack, onExit, calls };
}

const moved = { ...blank, id: 'moved', sourceId: 99, category: incorrect.category };
const groups: RevisionGroup[] = [
  { sourceId: source.id, category: incorrect.category, incorrect: 1, blank: 0, repeated: 0, questions: [incorrect] },
  // Same category, different source must be independently selectable.
  { sourceId: 99, category: incorrect.category, incorrect: 0, blank: 1, repeated: 0, questions: [moved] },
  { sourceId: source.id, category: 'Unavailable', incorrect: 0, blank: 1, repeated: 0, questions: [] },
];

describe('Revision topic selection', () => {
  it('counts available topics, selects, and generates only for the chosen source', async () => {
    const { user, onBack, onExit, calls } = mountSelection(groups, [incorrect, moved]);
    const boxes = screen.getAllByRole('checkbox');
    expect(boxes[0]).toBeChecked();
    expect(boxes[1]).toBeChecked();
    expect(boxes[2]).toBeDisabled();
    expect(screen.getByRole('status')).toHaveTextContent('2 of 2 available topics selected');
    expect(screen.queryByTestId('text-question')).not.toBeInTheDocument();
    await user.click(screen.getByRole('button', { name: 'Clear selection' }));
    expect(screen.getByTestId('button-start-revision')).toBeDisabled();
    expect(screen.getByText('Select at least one topic to start revision.')).toBeVisible();
    await user.click(screen.getByRole('button', { name: 'Select all topics' }));
    expect(boxes[2]).not.toBeChecked();
    await user.click(boxes[0]);
    expect(screen.getByRole('status')).toHaveTextContent('1 of 2 available topics selected');
    expect(calls).toEqual([]);
    await user.click(screen.getByTestId('button-start-revision'));
    expect((await screen.findByTestId('text-question')).textContent).toBe(moved.prompt);
    expect(calls[0].sourceIds).toEqual([99]);
    expect(screen.getByTestId('text-practice-score')).toHaveTextContent('bank of 1');
    const topics = screen.getByRole('list', { name: 'Revision topics' });
    expect(within(topics).getAllByRole('listitem')).toHaveLength(1);
    expect(topics).toHaveTextContent('Source 99');
    expect(screen.queryByTestId('text-explanation')).not.toBeInTheDocument();
    await user.click(screen.getByRole('button', { name: 'Back to exam results' }));
    expect(onBack).toHaveBeenCalledOnce();
    await user.click(screen.getByRole('button', { name: 'Exit targeted revision' }));
    expect(onExit).toHaveBeenCalledOnce();
  });

  it('resets the temporary attempt when choosing different topics', async () => {
    const { user } = mountSelection(groups, [incorrect, moved]);
    await user.click(screen.getAllByRole('checkbox')[1]);
    await user.click(screen.getByTestId('button-start-revision'));
    await user.click(await screen.findByTestId('button-choice-0'));
    await user.click(screen.getByTestId('button-check'));
    expect(screen.getByTestId('text-explanation')).toBeVisible();
    await user.type(screen.getByTestId('input-scratchpad'), 'old work');
    await user.click(screen.getByRole('button', { name: 'Choose different topics (resets practice)' }));
    expect(screen.queryByTestId('text-question')).not.toBeInTheDocument();
    const boxes = screen.getAllByRole('checkbox');
    await user.click(boxes[0]);
    await user.click(boxes[1]);
    await user.click(screen.getByTestId('button-start-revision'));
    expect((await screen.findByTestId('text-question')).textContent).toBe(moved.prompt);
    expect(screen.getByTestId('text-practice-score')).toHaveTextContent('Session: 0 of 0 correct');
    expect(screen.getByTestId('input-scratchpad')).toHaveValue('');
    expect(screen.queryByTestId('text-explanation')).not.toBeInTheDocument();
    expect(screen.getByTestId('button-check')).toBeDisabled();
  });

  it('shows all generated problems when none match the exact missed category', async () => {
    const other = { ...incorrect, id: 'other', category: 'Something else' };
    const { user } = mountSelection([groups[0]], [other]);
    await user.click(screen.getByTestId('button-start-revision'));
    expect((await screen.findByTestId('text-question')).textContent).toBe(other.prompt);
    expect(screen.getByTestId('text-revision-unmatched')).toBeVisible();
  });

  it.each([{ unavailable: [] }, { unavailable: [groups[2]] }])('cannot start when no topic has missed questions: $unavailable', ({ unavailable }) => {
    mountSelection(unavailable, []);
    expect(screen.getByTestId('button-start-revision')).toBeDisabled();
    expect(screen.getByRole('button', { name: 'Select all topics' })).toBeDisabled();
    expect(screen.getByText('No missed topics to revise.')).toBeVisible();
  });
});
